-- decimal field of a task variable; f = { var, first digit, width, daily }
function PTTM_Get(f)
	if f[4] then PTTM_DayCheck() end
	return mod(floor(GetTask(f[1]) / PTTM_P10[f[2] + 1]), PTTM_P10[f[3] + 1])
end

function PTTM_Set(f, v)
	if f[4] then PTTM_DayCheck() end
	local o = GetTask(f[1])
	local cur = mod(floor(o / PTTM_P10[f[2] + 1]), PTTM_P10[f[3] + 1])
	SetTask(f[1], o + (v - cur) * PTTM_P10[f[2] + 1])
end

-- daily fields: a new day clears 2263, the daily digits of 2256 and 2278 (d4-d8), and stamps 2278
function PTTM_DayCheck()
	local d = PTTM_Day4()
	if mod(GetTask(2278), 10000) ~= d then
		SetTask(2263, 0)
		SetTask(2278, d)
		SetTask(2256, mod(GetTask(2256), 100))
	end
end

function PTTM_Bit(v, b)
	return mod(floor(v / b), 2)
end

function PTTM_TmLevel()
	if GetPlayerExtLevel then
		local v = GetPlayerExtLevel()
		if v and v > 0 then return v end
