-- quest summon at a cell of the player's map (1073/1074): owner = player id, timeout = secs
function PTTM_SummonAt(tpl, lv, name, kind, secs, x, y)
	local m = GetWorldPos()
	if m ~= PTTM_MAP and m ~= PTTM_MAP2 then return 0 end
	local sw = SubWorldID2Idx(m)
	if sw == nil or sw < 0 then return 0 end
	local ni = AddNpc(tpl, lv, sw, x * 32, y * 32, 1)
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, (x + 2) * 32, y * 32, 1) end
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, x * 32, (y + 2) * 32, 1) end
	if ni == nil or ni <= 0 then return 0 end
	SetNpcName(ni, name)
	SetNpcScript(ni, PTTM_MOB_SCRIPT)
	SetNpcParam(ni, 0, GetPlayerID())
	SetNpcParam(ni, 1, kind)
	SetNpcTimeout(ni, secs * 18)
	PTTM_Set(F_SUMMON, ni)
	return ni
end

-- beside the player
function PTTM_Summon(tpl, lv, name, kind, secs)
	local m, x, y = GetWorldPos()
	return PTTM_SummonAt(tpl, lv, name, kind, secs, x + 3, y + 3)
end

function PTTM_SummonAlive(kind)
	local ni = PTTM_Get(F_SUMMON)
	if ni > 0 and GetNpcParam(ni, 1) == kind and GetNpcParam(ni, 0) == GetPlayerID() then return ni end
	return 0
end

-- task 92 Tru Lung Thao: one-shot talk of a listed NPC (key) while the player is in the talk stage.
-- Returns 1 when the dialog was used for it (the caller then stops).
PTTM_TLT_TIEN = "|xichtinhtu|taobao|thukho|tuhanhsu|tieuthang|moctra|tiepdan|bachhac|thanhhu|"
PTTM_TLT_MA = "|caogiac|tiepdan|thukho|tuhanhsu|molietho|linhnha|ovan|cauthu|kimquang|"
function PTTM_Tlt(key, name)
	if PTTM_Get(F_92S) ~= 1 then return nil end
	local lst = PTTM_TLT_TIEN
	if PTTM_IsMa() then lst = PTTM_TLT_MA end
	local p = strfind(lst, "|" .. key .. "|", 1, 1)
	if p == nil then return nil end
	-- index 1..9 = number of "|" before p
	local k, i = 0, 1
	while i <= p do
		if strsub(lst, i, i) == "|" then k = k + 1 end
		i = i + 1
	end
	local b = PTTM_P10[1]
	i = 1
	while i < k do
		b = b * 2
		i = i + 1
	end
	local m = PTTM_Get(F_92M)
	if PTTM_Bit(m, b) == 1 then return nil end
	m = m + b
	PTTM_Set(F_92M, m)
	local c, j = 0, 1
	while j <= 256 do
		if PTTM_Bit(m, j) == 1 then c = c + 1 end
		j = j * 2
	end
	Talk(1, "", "<color=green>" .. name .. "<color>: §­îc, ta chó nhËp ph¸p lùc vµo <color=yellow>Tr­ Lung Th¶o<color> cho ng­¬i. (" .. c .. "/9)")
	if c >= 9 then
		PTTM_Set(F_92S, 2)
		PTTM_Set(F_92C, 0)
		TaskNote(92, 1, 5)
		Msg2Player("Tr­ Lung Th¶o ®· ®ñ ph¸p lùc! H·y b¾t 5 <color=red>Trïng Hån<color> (diÖt Tr¹nh Nanh cã x¸c suÊt xuÊt hiÖn).")
	end
	return 1
end

