-- task 97: one more item / kill for the counting hexagrams (1 Can, 2 Doai, 3 Ly, 4 Chan, 6 Kham)
function PTTM_GuaStep(g)
	local need = 15
	if g == 2 then need = 5 elseif g == 3 or g == 4 then need = 10 elseif g == 6 then need = 30 end
	local rem = GetTask(PTTM_T_GUAN) - 1
	if rem > need then rem = need - 1 end
	if rem <= 0 then
		SetTask(PTTM_T_GUAN, 0)
		PTTM_GuaDone()
		return
	end
	SetTask(PTTM_T_GUAN, rem)
	TaskNote(97, g + 1, need - rem)
end

function PTTM_Gua(tpl, kind)
	if GetTaskByte(PTTM_T_GUA, 3) ~= 2 then return end
	local g = GetTaskByte(PTTM_T_GUA, 4)
	if g == 1 and tpl == 739 then
		if random(1, 100) <= 50 then PTTM_GuaStep(1) end
	elseif g == 2 and (tpl == 740 or tpl == 741) then
		PTTM_GuaStep(2)
	elseif g == 6 and tpl == 739 then
		PTTM_GuaStep(6)
	elseif g == 7 and tpl == 878 and kind == PTTM_K_KNSON then
		PTTM_GuaDone()
	elseif g == 7 and (tpl == 783 or tpl == 743) then
		if PTTM_SummonAlive(PTTM_K_KNSON) == 0 and random(1, 100) <= 25 then
			if PTTM_Summon(878, 80, "Ma Kh©m Nguyªn (S¬n)", PTTM_K_KNSON, 300) > 0 then
				TaskNote(97, 10)
				Msg2Player("§Çu lÜnh <color=red>Ma Kh©m Nguyªn (S¬n)<color> ®· xuÊt hiÖn!")
			end
		end
	elseif g == 8 and (tpl == 783 or tpl == 743) then
		if random(1, 100) <= 10 then
			Msg2Player("§· tiªu diÖt <color=red>Ma Kh©m Nguyªn (§Þa)<color>!")
			PTTM_GuaDone()
		end
	elseif g == 5 and tpl == 879 and kind == PTTM_K_THUCDUOC then
		PTTM_GuaDone()
	end
end

