-- all quests, called one after the other (flat: keeps the Lua stack shallow in the kill handler)
function PTTM_KillAll(tpl, kind)
	PTTM_KillOne(tpl, kind)
	PTTM_Gua(tpl, kind)
	PTTM_KillP2(tpl, kind)
	PTTM_KillP3(tpl, kind)
end

function PTTM_DailyId()
	if PTTM_Phe() == 2 then return 94 end
	return 93
end

-- killer and the team members on the same map get the credit
function PTTM_OnKill(npc)
	local tpl = GetNpcTemplateID(npc)
	local kind = GetNpcParam(npc, 1)
	local me = PlayerIndex
	local n = 0
	if GetTeamSize then n = GetTeamSize() end
	if n and n > 1 then
		local w = GetWorldPos()
		local i = 1
		while i <= n do
			local p = GetTeamMember(i)
			if p and p > 0 then
				PlayerIndex = p
				if GetWorldPos() == w then PTTM_KillAll(tpl, kind) end
			end
			i = i + 1
		end
		PlayerIndex = me
	else
		PTTM_KillAll(tpl, kind)
	end
end
